Error Handling and Validation

# Safe summary function with validation
safe_summarize &lt;- function(data, group_var, value_var) {
  group_var &lt;- enquo(group_var)
  value_var &lt;- enquo(value_var)

  # Validate inputs
  if (!quo_name(value_var) %in% names(data)) {
    stop("Value variable not found in data")
  }

  if (!is.numeric(data %&gt;% pull(!!value_var))) {
    warning("Value variable is not numeric, converting...")
    data &lt;- data %&gt;%
      mutate(!!value_var := as.numeric(!!value_var))
  }

  # Perform analysis with error handling
  tryCatch({
    data %&gt;%
      group_by(!!group_var) %&gt;%
      summarise(
        n = n(),
        mean = mean(!!value_var, na.rm = TRUE),
        median = median(!!value_var, na.rm = TRUE),
        sd = sd(!!value_var, na.rm = TRUE),
        missing = sum(is.na(!!value_var)),
        .groups = "drop"
      ) %&gt;%
      mutate(
        cv = sd / mean,  # Coefficient of variation
        data_quality = case_when(
          missing / n &gt; 0.1 ~ "Poor",
          cv &gt; 1 ~ "High Variability", 
          TRUE ~ "Good"
        )
      )
  }, error = function(e) {
    message("Error in summarization: ", e$message)
    return(NULL)
  })
}

# Test the function
result &lt;- safe_summarize(transactions, store_id, net_amount)
cat("Safe summarization completed successfully\n")

Safe summarization completed successfully

Error Handling in Functions

Using stop() and warning()

# Function with input validation
safe_divide &lt;- function(x, y) {
  # Check for valid inputs
  if (!is.numeric(x) || !is.numeric(y)) {
    stop("Both x and y must be numeric")
  }

  if (y == 0) {
    stop("Division by zero is not allowed")
  }

  if (y &lt; 0) {
    warning("Dividing by negative number")
  }

  result &lt;- x / y
  return(result)
}

# Test the function
safe_divide(10, 2)

[1] 5

safe_divide(10, -2)  # Will show warning

[1] -5

# safe_divide(10, 0)   # Would stop with error
# safe_divide("10", 2) # Would stop with error



Using try() and tryCatch()

# Function that handles errors gracefully
robust_mean &lt;- function(data, method = "arithmetic") {
  result &lt;- tryCatch({
    if (method == "arithmetic") {
      mean(data, na.rm = TRUE)
    } else if (method == "geometric") {
      if (any(data &lt;= 0, na.rm = TRUE)) {
        stop("Geometric mean requires positive values")
      }
      exp(mean(log(data), na.rm = TRUE))
    } else {
      stop("Method must be 'arithmetic' or 'geometric'")
    }
  }, error = function(e) {
    cat("Error occurred:", e$message, "\n")
    return(NA)
  }, warning = function(w) {
    cat("Warning:", w$message, "\n")
    return(NA)
  })

  return(result)
}

# Test error handling
test_data &lt;- c(2, 4, 8, 16)
negative_data &lt;- c(-1, 2, 4)

robust_mean(test_data, "arithmetic")

